195	  /**
196	   * Writes the root index after validation and automatically syncs .meta.json.
197	   *
198	   * @internal This method should only be called from within LedgerStore sync methods
199	   * (`updateWorkPackageWithSync`, `createWorkPackageWithSync`, `batchUpdateWorkPackagesWithSync`)
200	   * or from one of the following explicitly approved direct callers that manage their own
201	   * lock scope and cannot route through a sync method:
202	   *
203	   *   - `project-lifecycle.ts` — `getProjectStatus()` self-healing: repairs stale counter fields
204	   *     under an explicit `withLock` before returning project status; also used in
205	   *     `initializeProject()` and `completeSynthesis()` for root-index-only transitions that
206	   *     don't involve any WP file writes.
207	   *   - `auto-archive.ts`    — GUI auto-archive: sets `status: 'ARCHIVED'` with
208	   *     `preserveLastUpdated: true` so the visible activity time is not distorted.
209	   *   - `observations.ts`    — Project-level comment append: writes only the root index
210	   *     (no WP file involved) after appending a project comment.
211	   *   - `workflow-handoff.ts` — `buildHandoffResponse()`: increments or caps the
212	   *     `auto_handoff_depth` counter on every handoff-status response; root-index-only
213	   *     write with no WP file involvement.
214	   *
215	   * All other tool functions and helpers must NOT call this directly — use a sync method
216	   * instead to guarantee atomic WP+root writes, schema validation, `last_updated`
217	   * auto-stamping, and `.meta.json` sync.
218	   *
219	   * @param data    - Root index data to write
220	   * @param options - Optional flags; set `preserveLastUpdated: true` for
221	   *                  administrative status transitions (archive / unarchive)
222	   *                  that must not alter the project's visible activity time.
223	   * @throws Error if validation fails or write fails
224	   */
225	  async writeRootIndex(data: RootIndex, options?: { preserveLastUpdated?: boolean }): Promise<void> {
226	    // Validate before writing
227	    const validated = RootIndexSchema.parse(data);
228	
229	    const path = this.rootIndexPath();
230	    await atomicWriteJson(path, validated);
231	    // Auto-sync .meta.json after every root index write — include WP counters, progress, and runner metadata
232	    await this.writeProjectMeta('', validated.status, {
233	      total_work_packages: validated.total_work_packages,
234	      pending_work_packages: validated.pending_work_packages,
235	      progress_pct: computeProjectProgress(validated.work_packages),
236	      ...(validated.runner !== undefined ? { runner: validated.runner } : {}),
237	      ...(validated.runner_client !== undefined ? { runner_client: validated.runner_client } : {}),
238	      ...(validated.runner_version !== undefined ? { runner_version: validated.runner_version } : {}),
239	    }, options);
240	  }
