243	   * Writes a work package detail file after validation.
244	   *
245	   * @internal This method should only be called from within LedgerStore sync methods
246	   * (`updateWorkPackageWithSync`, `createWorkPackageWithSync`, `batchUpdateWorkPackagesWithSync`).
247	   * As of the WP-002 migration (consolidate-wp-writes), `writeWorkPackage` has NO legitimate
248	   * external callers — every code path that previously called it directly (including
249	   * `project-reset.ts`) has been migrated to use a sync method. Tool functions and
250	   * helpers must NOT call this directly — use a sync method instead to guarantee atomic

401	  async batchUpdateWorkPackagesWithSync(
402	    callback: (
403	      root: RootIndex,
404	      readWp: (id: string) => Promise<WorkPackageDetail>
405	    ) => Promise<{ updatedWps: Map<string, WorkPackageDetail>; root: RootIndex }>
406	  ): Promise<void> {
407	    await withLock(this.storageDir, async () => {
408	      // Read the root index inside the lock
409	      const root = await this.readRootIndex();
410	
411	      // Provide a readWp helper bound to this store
412	      const readWp = (id: string) => this.readWorkPackage(id);
413	
414	      // Run the callback to get the batch of updates
415	      const { updatedWps, root: updatedRoot } = await callback(root, readWp);
416	
417	      const timestamp = now();
418	
419	      // Sync passed_stages on each modified WP's summary entry
420	      for (const [wpId, wp] of updatedWps) {
421	        const wpSummary = updatedRoot.work_packages.find((s) => s.work_package_id === wpId);
422	        if (wpSummary) {
423	          wpSummary.passed_stages = computePassedStages(wp, wpSummary.active_pipeline_stages);
424	        }
425	      }
426	
427	      // Pass 1: auto-stamp and validate every WP — collect validated objects before any write.
428	      // This ensures a mid-batch validation failure cannot leave some WP files updated
429	      // while the root index still reflects the pre-batch state (WP/root desync).
430	      const validatedEntries: Array<[string, WorkPackageDetail]> = [];
431	      for (const [wpId, wp] of updatedWps) {
432	        // Auto-stamp last_updated on every WP write (mirrors updateWorkPackageWithSync)
433	        wp.last_updated = timestamp;
434	        validatedEntries.push([wpId, WorkPackageDetailSchema.parse(wp)]);
435	      }
436	
437	      // Also validate the root index before writing anything
438	      const validatedRoot = RootIndexSchema.parse(updatedRoot);
439	
440	      // Pass 2: write all validated WPs atomically (no validation can fail from here)
441	      for (const [wpId, validatedWp] of validatedEntries) {
442	        await atomicWriteJson(this.wpDetailPath(wpId), validatedWp);
443	      }
444	      await atomicWriteJson(this.rootIndexPath(), validatedRoot);
445	
446	      // Sync .meta.json exactly once after all WP writes — include progress
447	      await this.writeProjectMeta('', validatedRoot.status, {
448	        total_work_packages: validatedRoot.total_work_packages,
449	        pending_work_packages: validatedRoot.pending_work_packages,
450	        progress_pct: computeProjectProgress(validatedRoot.work_packages),
451	      });
452	    });
453	  }
