455	  // ==================== Meta Methods ====================
456	
457	  /**
458	   * Creates or updates the project's .meta.json file.
459	   * On first write: populates all fields. On subsequent writes: updates status and last_updated
460	   * (unless `options.preserveLastUpdated` is true, in which case the existing value is kept).
461	   * Must be called within the project lock when triggered from a root-index write.
462	   *
463	   * @param planFile     - Plan file name (used only on first write; ignored on updates)
464	   * @param status       - Optional status override; defaults to existing status or IN_PROGRESS
465	   * @param cacheUpdates - Optional WP counter / enrichment fields to write into the cache
466	   * @param options      - Set `preserveLastUpdated: true` to retain the existing timestamp
467	   *                       (use for admin operations: archive, unarchive, cache refresh).
468	   */
469	  async writeProjectMeta(
470	    planFile: string,
471	    status?: string,
472	    cacheUpdates?: MetaCacheUpdates,
473	    options?: { preserveLastUpdated?: boolean }
474	  ): Promise<void> {
475	    const path = this.metaPath();
476	    let existing: Partial<ProjectMeta> = {};
477	
478	    try {
479	      const content = await readFile(path, 'utf-8');
480	      existing = JSON.parse(content) as Partial<ProjectMeta>;
481	    } catch {
482	      // First write — all fields will be initialised below
483	    }
484	
485	    const timestamp = now();
486	    // Preserve the existing last_updated for administrative operations (archive,
487	    // unarchive, enrichment cache refresh) that should not distort sort order.
488	    const lastUpdated =
489	      options?.preserveLastUpdated && existing.last_updated
490	        ? existing.last_updated
491	        : timestamp;
492	    const meta = ProjectMetaSchema.parse({
493	      slug: existing.slug ?? this.slug,
494	      plan_path: existing.plan_path ?? this.planPath,
495	      status: (status ?? existing.status ?? 'IN_PROGRESS') as ProjectMeta['status'],
496	      date_created: existing.date_created ?? timestamp,
497	      last_updated: lastUpdated,
498	      ...(existing.title !== undefined ? { title: existing.title } : {}),
499	      // Preserve existing cache fields unless overridden by cacheUpdates
500	      ...(existing.total_work_packages !== undefined ? { total_work_packages: existing.total_work_packages } : {}),
501	      ...(existing.pending_work_packages !== undefined ? { pending_work_packages: existing.pending_work_packages } : {}),
502	      ...(existing.progress_pct !== undefined ? { progress_pct: existing.progress_pct } : {}),
503	      ...(existing.project_name !== undefined ? { project_name: existing.project_name } : {}),
504	      ...(existing.repository_name !== undefined ? { repository_name: existing.repository_name } : {}),
505	      // Apply overrides from cacheUpdates (undefined values skip the field)
506	      ...(cacheUpdates?.total_work_packages !== undefined ? { total_work_packages: cacheUpdates.total_work_packages } : {}),
507	      ...(cacheUpdates?.pending_work_packages !== undefined ? { pending_work_packages: cacheUpdates.pending_work_packages } : {}),
508	      ...(cacheUpdates?.progress_pct !== undefined ? { progress_pct: cacheUpdates.progress_pct } : {}),
509	      ...(cacheUpdates !== undefined && 'project_name' in cacheUpdates ? { project_name: cacheUpdates.project_name } : {}),
510	      ...(cacheUpdates !== undefined && 'repository_name' in cacheUpdates ? { repository_name: cacheUpdates.repository_name } : {}),
511	      // Runner metadata: preserve existing values (backward compat), then apply overrides
512	      ...(existing.runner !== undefined ? { runner: existing.runner } : {}),
513	      ...(existing.runner_client !== undefined ? { runner_client: existing.runner_client } : {}),
514	      ...(existing.runner_version !== undefined ? { runner_version: existing.runner_version } : {}),
515	      ...(cacheUpdates !== undefined && 'runner' in cacheUpdates && cacheUpdates.runner !== undefined ? { runner: cacheUpdates.runner as 'vscode' | 'claude-code' | 'orchestrator' | 'unknown' } : {}),
516	      ...(cacheUpdates !== undefined && 'runner_client' in cacheUpdates ? { runner_client: cacheUpdates.runner_client } : {}),
517	      ...(cacheUpdates !== undefined && 'runner_version' in cacheUpdates ? { runner_version: cacheUpdates.runner_version } : {}),
518	    });
519	
520	    await atomicWriteJson(path, meta);
521	  }
