563	  /**
564	   * Renames the ledger storage directory and updates the `slug` field in `.meta.json`.
565	   *
566	   * Algorithm:
567	   *   1. Validates `newSlug` against SAFE_SLUG_REGEX and the 200-char length cap.
568	   *   2. Guards against a same-slug no-op and a target-directory conflict.
569	   *   3. Calls `fs.rename(oldStorageDir, newStorageDir)` — atomic on POSIX, effectively
570	   *      atomic on Windows for same-drive renames.
571	   *   4. Reads `.meta.json` from the **new** path (old path is gone), patches `slug`,
572	   *      and writes back with `atomicWriteJson`. Does **not** touch `last_updated`.
573	   *
574	   * Error conditions:
575	   *   - `Invalid slug "…"` — pattern or length violation.
576	   *   - `Slug is already "…"` — same-slug no-op.
577	   *   - `Slug already in use: "…"` — target directory already exists.
578	   *
579	   * Lock behaviour: intentionally **not** wrapped in `withLock`. `withLock` creates
580	   * `.lock` inside `storageDir`; holding that lock across `fs.rename` would move the
581	   * lock file to the new path, causing `proper-lockfile` to fail to release at the
582	   * original path. The same low-concurrency reasoning that justifies `updateTitle()`
583	   * running lock-free applies here.
584	   *
585	   * ⚠️  After this method returns, the current `LedgerStore` instance is stale:
586	   * `this.storageDir` and `this.slug` still point to the old (now-deleted) directory.
587	   * The GUI reconstructs `LedgerStore` per-request, so this is safe in practice.
588	   * Do not reuse the same instance after calling `renameSlug()`.
589	   */
590	  async renameSlug(newSlug: string): Promise<ProjectMeta> {
591	    if (newSlug.length > 200 || !SAFE_SLUG_REGEX.test(newSlug)) {
592	      throw new Error(
593	        `Invalid slug "${newSlug}": must match ^[a-z0-9][a-z0-9-]*$ and be at most 200 characters.`
594	      );
595	    }
596	    if (newSlug === this.slug) {
597	      throw new Error(`Slug is already "${newSlug}"; no rename needed.`);
598	    }
599	    const newStorageDir = join(this.ledgerRoot, this.repoName, newSlug);
600	    try {

